void look_31(inout Look k) {
  p_plColour = L31_plColour;
  p_plStipple = L31_plStipple;
  p_plRelief = L31_plRelief;
  p_plRough = L31_plRough;
  p_plRoughVar = L31_plRoughVar;
  p_plTone = L31_plTone;
  p_plThrough = L31_plThrough;
  vec2 uv = vLookUv;
