Look lookRun(int id) {
  Look k = lookStart();
  switch (id) {
    case 27: look_27(k); break;
    case 28: look_28(k); break;
    case 56: look_56(k); break;
  }
  if (lookDebug > 0.5) {
    switch (id) {
      case 27: k.colour = vec3(0.6866853124353135, 0.7454042095403874, 0.7454042095403874); break;
      case 28: k.colour = vec3(0.005181516702338386, 0.006995410187265387, 0.009134058702220787); break;
      case 56: k.colour = vec3(0.25415209433082675, 0.3712376804741491, 0.4232676699860717); break;
    }
  }
  return k;
}
float lookShadow(int id, vec3 Lview) {

  return 1.0;
