void look_21(inout Look k) {
  p_vlColour = L21_vlColour;
  p_vlDeep = L21_vlDeep;
  p_vlPile = L21_vlPile;
  p_vlRelief = L21_vlRelief;
  p_vlLay = L21_vlLay;
  p_vlCrush = L21_vlCrush;
  p_vlRub = L21_vlRub;
  p_vlSheen = L21_vlSheen;
  p_vlSheenRough = L21_vlSheenRough;
  p_vlSeam = L21_vlSeam;
  p_vlSeamDark = L21_vlSeamDark;
  p_vlStitch = L21_vlStitch;
  p_vlThread = L21_vlThread;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 vlG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the lay, across it
    vec2 vlQ = vec2(dot(uv, vlG), dot(uv, vec2(-vlG.y, vlG.x))) + vec2(seed * 0.37, seed * 0.71);
    // the pile's tufts: fibre ends catching light, gone to their mean under a pixel
    float vlF = kfade(p_vlPile * 2.0);
    float vlT = mix(0.5, 0.6 * kn(vlQ / p_vlPile) + 0.4 * kn(vlQ / (p_vlPile * 0.4) + 3.7), vlF);
    // the crush: soft streaks drawn out along the lay, where the pile has been pushed over
    float vlCr = kfbm(vec2(vlQ.x * 3.0, vlQ.y * 14.0) + seed) - 0.5;
    float vlRubA = clamp(s0.z, 0.0, 1.0) * p_vlRub;
    // the lay: lighter where the eye looks along the pile than against it (the view's way laid onto the surface)
    float vlFace = 1.0 - abs(dot(normalize(-vViewPosition), normalize(vNormal)));
    vec3 vlC = mix(p_vlDeep, p_vlColour, 0.55 + 0.45 * vlT);
    vlC *= 1.0 + p_vlCrush * vlCr * 1.6 - vlRubA * 0.25;
    vlC *= 1.0 + p_vlLay * (vlFace - 0.4);
    // the seam: the pile pulled down into a furrow either side of the thread, its stitches beside it
    float vlD = s0.x;
    float vlSF = kfade(p_vlSeam);
    float vlFur = (1.0 - smoothstep(0.0, p_vlSeam, vlD)) * vlSF;
    float vlSt = 0.0;
    if (vlD < p_vlSeam * 3.0) {
      float vlAl = fract(s0.y / p_vlStitch);
      float vlRow = 1.0 - smoothstep(0.0003, 0.0008, abs(vlD - p_vlSeam * 1.3));
      vlSt = vlRow * smoothstep(0.08, 0.2, vlAl) * (1.0 - smoothstep(0.62, 0.74, vlAl)) * kfade(p_vlStitch * 0.6);
    }
    vlC = mix(vlC, p_vlDeep * 0.6, p_vlSeamDark * vlFur);
    vlC = mix(vlC, p_vlThread, vlSt * 0.85);
    k.colour = vlC;
    k.rough = mix(0.96, 0.85, vlRubA);
    k.height = p_vlRelief * (vlT - 0.5) * (1.0 - 0.6 * vlRubA) - p_vlSeam * 0.6 * vlFur + 0.0002 * vlSt;
    k.ao = mix(0.82, 1.0, vlT) * (1.0 - 0.45 * vlFur);
    k.sheen = mix(p_vlColour * 2.4, vec3(1.0), 0.18) * p_vlSheen * (1.0 - 0.5 * vlFur) * (1.0 + p_vlCrush * vlCr);
    k.sheenRough = p_vlSheenRough;
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(vlFur, vlSt, vlRubA);

}

void look_22(inout Look k) {
