void look_32(inout Look k) {
  p_clColour = L32_clColour;
  p_clRub = L32_clRub;
  p_clGrain = L32_clGrain;
  p_clGrainDepth = L32_clGrainDepth;
  p_clCreases = L32_clCreases;
  p_clCrease = L32_clCrease;
  p_clWear = L32_clWear;
  p_clRough = L32_clRough;
  p_clRubRough = L32_clRubRough;
  p_clCoat = L32_clCoat;
  p_clSheen = L32_clSheen;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the pebbled grain: cells pressed into the hide, high in their middles, furrowed at their edges
    float clId, clE;
    kvor(uv * p_clGrain + seed, clId, clE);
    float clSee = kfade(2.0 / p_clGrain);
    float clPeb = mix(0.7, smoothstep(0.0, 0.25, clE), clSee);
    float clCell = (kh1(clId) - 0.5) * clSee;
    // the dye's mottle over the hide
    float clMott = kfbm4(uv * 6.0 + seed);
    // soft creases: thin lines wandering every way over the hide where it bends (the contours of a slow noise), each
    // its own strength, some stretches with none
    float clN = kfbm(uv * p_clCreases * 0.3 + seed + 4.0);
    float clCr = (1.0 - smoothstep(0.0, 0.035, abs(clN - 0.5))) * smoothstep(0.4, 0.7, kfbm(uv * 3.0 + seed + 11.0));
    clCr *= p_clCrease * kfade(0.2 / p_clCreases);
    // the rubbing: the hide's own wear in patches, and the kind's hint where it is sat on or gripped
    float clRubA = clamp(p_clWear * smoothstep(0.5, 0.85, kfbm4(uv * 4.0 + seed + 2.0)) + s0.x, 0.0, 1.0);
    vec3 clC = p_clColour * (0.92 + 0.16 * clMott) * (1.0 + 0.035 * clCell);
    clC *= 0.94 + 0.06 * clPeb;
    clC = mix(clC, p_clRub, clRubA * 0.6);
    clC *= 1.0 - 0.18 * clCr;
    k.colour = clC;
    // rubbed smooth: the grain worn flatter and glossier where the hide is rubbed
    k.rough = clamp(mix(p_clRough, p_clRubRough, clRubA) + 0.08 * (1.0 - clPeb), 0.0, 1.0);
    k.height = p_clGrainDepth * clPeb * (1.0 - 0.6 * clRubA) - 0.0004 * clCr;
    k.ao = mix(0.85, 1.0, clPeb);
    k.clearcoat = p_clCoat;
    k.clearcoatRough = 0.35;
    k.sheen = mix(p_clColour, vec3(1.0), 0.5) * p_clSheen;
    k.sheenRough = 0.5;

}

void look_33(inout Look k) {
  p_rmColour = L33_rmColour;
  p_rmWorn = L33_rmWorn;
  p_rmDirt = L33_rmDirt;
