void look_51(inout Look k) {
  p_apColour = L51_apColour;
  p_apFlake = L51_apFlake;
  p_apFlakeColour = L51_apFlakeColour;
  p_apFlakeSize = L51_apFlakeSize;
  p_apRough = L51_apRough;
  p_apCoat = L51_apCoat;
  p_apCoatRough = L51_apCoatRough;
  p_apPeel = L51_apPeel;
  p_apPeelDepth = L51_apPeelDepth;
  p_apDust = L51_apDust;
  p_apDustColour = L51_apDustColour;
  p_apDustHeight = L51_apDustHeight;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // flake: one fleck a cell, each its own brightness and its own tilt, fading to its mean where a fleck is under a pixel
    vec2 apC = floor(uv / p_apFlakeSize);
    float apS = kh(apC + seed);
    float apSee = kfade(p_apFlakeSize * 3.0);
    float apFleck = mix(0.5, step(0.55, apS) * (0.4 + 0.6 * kh(apC + seed + 17.0)), apSee) * p_apFlake;
    vec3 apBase = p_apColour * (0.97 + 0.06 * kfbm4(uv * 1.5 + seed));
    k.colour = mix(apBase, apBase * 0.4 + p_apFlakeColour * 0.6, apFleck * 0.35);
    k.metal = p_apFlake * 0.6;
    k.rough = clamp(p_apRough - 0.15 * apFleck, 0.0, 1.0);
    float apPeelF = kfade(2.0 / p_apPeel);
    float apP = (1.0 - kcell(uv * p_apPeel + seed)) * apPeelF;
    k.height = p_apPeelDepth * apP + 0.000004 * (apS - 0.5) * apSee * p_apFlake;
    k.clearcoat = p_apCoat;
    k.clearcoatRough = p_apCoatRough;
    // road dust: thick at the ground, gone by apDustHeight, broken up so it reads as spray, not a band
    float apLow = 1.0 - smoothstep(0.0, p_apDustHeight, wp.y);
    float apSpray = smoothstep(0.25, 0.85, kfbm(uv * 6.0 + seed + 3.0) + 0.35 * apLow);
    float apD = clamp(p_apDust * apLow * apSpray * 1.4, 0.0, 1.0);
    k.colour = mix(k.colour, p_apDustColour * (0.85 + 0.3 * kn(uv * 60.0 + seed)), apD);
    k.rough = mix(k.rough, 0.85, apD);
    k.metal = mix(k.metal, 0.0, apD);
    k.clearcoat = mix(k.clearcoat, 0.0, apD);

}

void look_52(inout Look k) {
  p_tpColour = L52_tpColour;
  p_tpFaded = L52_tpFaded;
