  p_tpGrain = L52_tpGrain;
  p_tpGrainDepth = L52_tpGrainDepth;
  p_tpRough = L52_tpRough;
  p_tpDust = L52_tpDust;
  p_tpDustColour = L52_tpDustColour;
  p_tpDustHeight = L52_tpDustHeight;
  vec2 uv = vLookUv;
