void look_59(inout Look k) {
  p_trColour = L59_trColour;
  p_trScrub = L59_trScrub;
  p_trDust = L59_trDust;
  p_trDustAmount = L59_trDustAmount;
  p_trGrit = L59_trGrit;
  p_trRelief = L59_trRelief;
  p_trRough = L59_trRough;
  p_trSheen = L59_trSheen;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float trG = kn(uv * p_trGrit + seed) * kfade(2.0 / p_trGrit);
